#include <stdio.h>

int main(void) {
    unsigned long long x = 48523ULL;
    unsigned int count = 0;

    while (x != 0) {
        count += (unsigned int)(x & 1ULL);
        x >>= 1;
    }

    printf("%u\n", count);
    return 0;
}

