#include <stdio.h>

struct Node {
    int value;
    struct Node *next;
};

int main(void) {
    struct Node nodes[5];

    nodes[0].value = 10;
    nodes[0].next = &nodes[1];

    nodes[1].value = 20;
    nodes[1].next = &nodes[2];

    nodes[2].value = 30;
    nodes[2].next = &nodes[3];

    nodes[3].value = 40;
    nodes[3].next = &nodes[4];

    nodes[4].value = 50;
    nodes[4].next = 0;

    int sum = 0;
    struct Node *current = &nodes[0];

    while (current != 0) {
        sum += current->value;
        current = current->next;
    }

    printf("%d\n", sum);

    return 0;
}

