#include <stdio.h>

typedef struct {
    int a;
    int b;
    int c;
} Record;

void set_fields(Record *r, int a, int b, int c) {
    r->a = a;
    r->b = b;
    r->c = c;
}

int get_a(const Record *r) {
    return r->a;
}

int get_b(const Record *r) {
    return r->b;
}

int get_c(const Record *r) {
    return r->c;
}

int main(void) {
    Record rec;

    set_fields(&rec, 11, 22, 33);

    printf("%d %d %d\n", get_a(&rec), get_b(&rec), get_c(&rec));

    return 0;
}

