#include <stdio.h>

int is_prime(int n) {
    if (n < 2) return 0;
    if (n == 2) return 1;
    if (n % 2 == 0) return 0;

    for (int i = 3; i <= n / i; i += 2) {
        if (n % i == 0) return 0;
    }

    return 1;
}

int main(void) {
    int numbers[] = {1, 2, 13, 15, 97};

    for (int i = 0; i < 5; i++) {
        printf("%d\n", is_prime(numbers[i]));
    }

    return 0;
}

#include <stdio.h>

int gcd(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

int main(void) {
    printf("%d\n", gcd(48, 36));
    return 0;
}

